     "ex": "# build once (week 45), then deploy the same image\ngcloud run deploy shop-api \\\n  --image=europe-west1-docker.pkg.dev/acme/shop/shop-api@sha256:4f1c… \\\n  --region=me-central2 \\\n  --min-instances=0 --max-instances=10 \\\n  --concurrency=40 --cpu=1 --memory=512Mi --timeout=60 \\\n  --set-secrets=DATABASE_URL=shop-db-url:latest \\\n  --service-account=shop-api@acme.iam.gserviceaccount.com",
